mapper.select:
SELECT RVC.IRVCATE_NO, RVC.STITLE, RVC.ISEQ, RVC.SHIDE_DT, RVC.SINS_DT, RVC.ILAW_ID, RVC.STEMP, RVC.SORGNDOWN_YN, ( SELECT COUNT(RF.IRFILE_NO) FROM TB_REL_VRSN RV JOIN TB_REL_FILE RF ON RV.IRVRSN_NO = RF.IRVRSN_NO WHERE RV.IRVCATE_NO = RVC.IRVCATE_NO AND RF.SDEL_YN = 'N' ) AS CNT FROM TB_REL_VRSN_CATE RVC WHERE RVC.ILAW_ID = #{lawId} AND ( RVC.STEMP = TO_CHAR(#{promNo})
OR RVC.STEMP IN ( SELECT TO_CHAR(P2.IPROM_NO) FROM TB_PROM P2, TB_PROM P0 WHERE P2.ILAW_ID = #{lawId} AND P0.IPROM_NO = #{promNo} AND P2.ILAW_NO <= P0.ILAW_NO )
) AND ( RVC.SHIDE_DT = '0' OR RVC.SHIDE_DT >= #{today} ) ORDER BY RVC.ISEQ, RVC.IRVCATE_NO

SELECT IRVCATE_NO, STITLE, ISEQ, SHIDE_DT, SINS_DT, ILAW_ID, STEMP, SORGNDOWN_YN
  FROM TB_REL_VRSN_CATE
 WHERE IRVCATE_NO = #{cateNo}

mapper.update:
UPDATE TB_REL_VRSN_CATE
   SET STITLE       = #{title},
       ISEQ         = #{seq,jdbcType=NUMERIC},
       SHIDE_DT     = #{hideDt,jdbcType=VARCHAR},
       SORGNDOWN_YN = #{orgnDownYn,jdbcType=VARCHAR}
 WHERE IRVCATE_NO = #{cateNo}
